import { focusRing } from "@/lib/beton/shared";
import { tv, type VariantProps } from "@/lib/beton/tv";

export const accordion = tv({
  slots: {
    root: "flex w-full flex-col border-3 border-border bg-raised",
    item: "border-b-3 border-border last:border-b-0",
    header: "flex",
    trigger: [
      "group flex w-full cursor-pointer items-center justify-between gap-4 text-left",
      "font-display font-extrabold text-foreground",
      "hover:bg-secondary data-panel-open:bg-secondary",
      "data-disabled:cursor-not-allowed data-disabled:bg-disabled data-disabled:text-disabled-foreground",
      focusRing,
    ],
    icon: [
      "size-5 shrink-0 transition-transform duration-70 ease-linear motion-reduce:transition-none",
      "group-data-panel-open:rotate-180",
    ],
    panel: [
      "h-(--accordion-panel-height) overflow-hidden border-t-3 border-border",
      "transition-[height] duration-100 ease-linear motion-reduce:transition-none",
      "data-starting-style:h-0 data-ending-style:h-0",
    ],
    content: "flex flex-col gap-3",
  },
  variants: {
    size: {
      sm: { trigger: "min-h-11 px-4 text-base", content: "px-4 py-3 text-sm" },
      md: { trigger: "min-h-14 px-5 text-lg", content: "px-5 py-4" },
      lg: { trigger: "min-h-16 px-6 text-xl", content: "px-6 py-5 text-lg" },
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export type AccordionVariants = VariantProps<typeof accordion>;

"use client";

import { Accordion as BaseAccordion } from "@base-ui/react/accordion";
import { accordion, type AccordionVariants } from "@/lib/beton/recipes/accordion.recipe";
import { createContext, useContext } from "react";
import { ChevronDownIcon } from "@/lib/beton/icons";

type Styles = ReturnType<typeof accordion>;

const AccordionContext = createContext<Styles>(accordion());

function useStyles() {
  return useContext(AccordionContext);
}

export interface AccordionProps
  extends Omit<BaseAccordion.Root.Props, "className">, AccordionVariants {
  className?: string;
}

function AccordionRoot({ size = "md", className, ...props }: AccordionProps) {
  const styles = accordion({ size });
  return (
    <AccordionContext.Provider value={styles}>
      <BaseAccordion.Root {...props} className={styles.root({ class: className })} />
    </AccordionContext.Provider>
  );
}

export interface AccordionItemProps extends Omit<BaseAccordion.Item.Props, "className"> {
  className?: string;
}

function AccordionItem({ className, ...props }: AccordionItemProps) {
  return <BaseAccordion.Item {...props} className={useStyles().item({ class: className })} />;
}

export interface AccordionTriggerProps extends Omit<BaseAccordion.Trigger.Props, "className"> {
  className?: string;
  /** The heading level the trigger sits in. Defaults to `h3`. */
  headingLevel?: 2 | 3 | 4 | 5 | 6;
  /** Show the chevron that turns when the panel opens. On by default. */
  icon?: boolean;
}

function AccordionTrigger({
  className,
  children,
  headingLevel = 3,
  icon = true,
  ...props
}: AccordionTriggerProps) {
  const styles = useStyles();
  const Heading = `h${headingLevel}` as const;
  return (
    <BaseAccordion.Header className={styles.header()} render={<Heading />}>
      <BaseAccordion.Trigger {...props} className={styles.trigger({ class: className })}>
        {children}
        {icon ? <ChevronDownIcon className={styles.icon()} /> : null}
      </BaseAccordion.Trigger>
    </BaseAccordion.Header>
  );
}

export interface AccordionPanelProps extends Omit<BaseAccordion.Panel.Props, "className"> {
  className?: string;
  /** Classes for the inner element that holds the content. */
  contentClassName?: string;
}

function AccordionPanel({ className, contentClassName, children, ...props }: AccordionPanelProps) {
  const styles = useStyles();
  return (
    <BaseAccordion.Panel {...props} className={styles.panel({ class: className })}>
      <div className={styles.content({ class: contentClassName })}>{children}</div>
    </BaseAccordion.Panel>
  );
}

/** Sections of content that open one at a time, or several at once with `multiple`. */
export const Accordion = Object.assign(AccordionRoot, {
  Item: AccordionItem,
  Trigger: AccordionTrigger,
  Panel: AccordionPanel,
});
